        "palette": [],
        "view": "ui",
        "sampling": "nearest",
        "alpha": "full",
        "intent": "One static 16x16 Ready status image for later delivery to the consumer path assets/ready-confirmed.png. Owner requirements: check mark with asymmetrical arms conveying successful completion, transparent background, cool blue accent, no fixed palette (partial alpha permitted). Specialist sample choices, revisable at style review: short left arm with longer right arm, chunky ~2px strokes, sky blue near #70b9ed with one lighter highlight, no backing plate or shadow."
      },
      "criteria": [
        {
          "id": "geometry",
          "domain": "mechanical",
          "mode": "local",
