            {"path": "src/queue-view.ts", "locator": "statusVisuals.succeeded frames 1", "lines": [6, 6]},
            {"path": "src/queue-view.ts", "locator": "display.cell [16, 16]", "lines": [9, 9]}
          ]
        },
        {
          "id": "transparent-background",
          "domain": "mechanical",
          "mode": "local",
          "check": "The background is transparent: pixels outside the subject have alpha 0 and no opaque matte, box or fringe fills the cell. Partial alpha on subject pixels is permitted; binary alpha is not required.",
          "basis": "Owner brief requires transparent backgrounds and the current update keeps them; it does not restrict alpha to binary values.",
          "scope": "This Ready candidate file.",
          "authority": "requirement",
          "sources": [
            {"path": "BRIEF.md", "locator": "Use transparent backgrounds", "lines": [3, 3]},
            {"path": "BRIEF.md", "locator": "Current update: keep ... transparent background", "lines": [9, 9]}
          ]
        },
        {
          "id": "check-mark-asymmetrical-arms",
          "domain": "visual",
          "mode": "visual",
          "check": "The image visibly uses a check mark whose two arms are of clearly unequal length (asymmetrical), and that mark conveys successful completion. Either arm may be the longer one, and stroke weight, colour treatment and construction are not restricted by this criterion.",
          "basis": "Owner requirement from the current brief update: Ready must visibly use a check mark with asymmetrical arms to convey successful completion.",
          "scope": "This Ready candidate at 1x and 3x nearest on #172336.",
          "authority": "requirement",
          "sources": [
            {"path": "BRIEF.md", "locator": "Current update: Ready must visibly use a check mark with asymmetrical arms to convey successful completion", "lines": [9, 9]}
